// Contract tests: Generate API key (GET /api/v1/auth)
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Content-Type is application/json", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

const schema = {
    type: "object",
    required: ["apiKey"],
    properties: {
        apiKey: { type: "string" }
    }
};

pm.test("Response body matches API key schema", function () {
    pm.response.to.have.jsonSchema(schema);
});

pm.test("Response time is under 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

// Capture API key for downstream authenticated requests
if (pm.response.code >= 200 && pm.response.code < 300) {
    const response = pm.response.json();
    pm.collectionVariables.set("apiKey", response.apiKey);
}

