// Set accountName: use environment value if present, otherwise generate a random full name
const envAccountName = pm.environment.get('accountName');
if (envAccountName) {
    pm.collectionVariables.set('accountName', envAccountName);
} else {
    pm.collectionVariables.set('accountName', pm.variables.replaceIn('{{$randomFullName}}'));
}

// Contract tests: Create new account (POST /api/v1/accounts)
pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Content-Type is application/json", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

const schema = {
    type: "object",
    required: ["account"],
    properties: {
        account: {
            type: "object",
            required: ["accountId"],
            properties: {
                accountId: { type: "string" }
            }
        }
    }
};

pm.test("Response body matches create-account schema", function () {
    pm.response.to.have.jsonSchema(schema);
});

pm.test("Response time is under 2000ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});


pm.test("Request includes Idempotency-Key header", function () {
    const headerValue = pm.request.headers.get("Idempotency-Key");
    pm.expect(headerValue, "Idempotency-Key header must be present on the request").to.exist;
    pm.expect(String(headerValue).trim(), "Idempotency-Key header must not be empty").to.not.equal("");
});

pm.test("Idempotency-Key header has a practical format", function () {
    const headerValue = String(pm.request.headers.get("Idempotency-Key") || "").trim();
    pm.expect(headerValue.length, "Idempotency-Key should be at least 8 characters long").to.be.at.least(8);
    pm.expect(headerValue, "Idempotency-Key should contain visible non-whitespace characters").to.match(/^\S+$/);
});

pm.test("Idempotent-Replayed response header is boolean-compatible when present", function () {
    const replayed = pm.response.headers.get("Idempotent-Replayed");
    if (replayed !== undefined && replayed !== null) {
        pm.expect(String(replayed).trim().toLowerCase()).to.be.oneOf(["true", "false", "1", "0"]);
    }
});

// Capture accountId for downstream chaining
if (pm.response.code >= 200 && pm.response.code < 300) {
    const response = pm.response.json();
    pm.collectionVariables.set("accountId", response.account.accountId);
}

