// Attach the captured API key to authenticated requests (skip the auth-generation endpoint which uses Basic auth)
const apiKey = pm.collectionVariables.get("apiKey") || pm.environment.get("apiKey");
if (apiKey && !pm.request.url.toString().includes("/api/v1/auth")) {
    pm.request.headers.upsert({ key: "x-api-key", value: apiKey });
}
